window.addEventListener("scroll",(()=>{document.getElementById("siteHeader").classList.toggle("scrolled",window.scrollY>50)})),document.addEventListener("DOMContentLoaded",(()=>{const e=document.getElementById("menuToggle"),t=document.getElementById("slideMenu"),s=document.getElementById("overlayBg"),c=document.getElementById("btnClose");e.addEventListener("click",(()=>{t.classList.add("active"),s.classList.add("active"),e.classList.add("active")})),c.addEventListener("click",(()=>{t.classList.remove("active"),s.classList.remove("active"),e.classList.remove("active")})),s.addEventListener("click",(()=>{t.classList.remove("active"),s.classList.remove("active"),e.classList.remove("active")}))}));